with valid as (select id, account_id, txn_type, amount, txn_time, merchant, cast(txn_time as date) as txn_time_day from transactions where merchant is not null and merchant = 'Shell'), gaps as (select *, case when lag(txn_time) over (partition by merchant order by txn_time, id) is null or txn_time > lag(txn_time) over (partition by merchant order by txn_time, id) + interval '14' day then 1 else 0 end as is_new_session from valid), sessions_transactions as (select *, sum(is_new_session) over (partition by merchant order by txn_time, id rows between unbounded preceding and current row) as island_id from gaps) select txn_type, round(avg(amount), 2) as avg_amount, max(txn_time) as ended_at from sessions_transactions group by txn_type order by txn_type
